import * as THREE from 'three';

// Generated by scripts/generate-regolith.mjs: seamless packed-grain albedo and
// tangent-space normals, with no directional lighting baked into the textures.
export function createRegolithMaps(){
  const loader=new THREE.TextureLoader();
  function load(name,colorSpace){
    const map=loader.load(`${import.meta.env.BASE_URL}textures/regolith-${name}.png`);
    map.colorSpace=colorSpace;map.flipY=false;map.wrapS=map.wrapT=THREE.RepeatWrapping;
    map.repeat.set(440/8,440/8);map.anisotropy=16;return map;
  }
  return {map:load('color',THREE.SRGBColorSpace),normalMap:load('normal',THREE.NoColorSpace),normalScale:new THREE.Vector2(.85,.85)};
}
